\title{The Scheme-Theoretic Stabilizer of a Regular Unipotent Class \\ under the Center of the Simply Connected Cover}
\author{Aristotle}
\date{2026-07-04}

\begin{document}

\begin{abstract}
Let $G$ be a reductive algebraic group over an algebraically closed field $k$, with simply connected cover $\pi\colon G'\to G$ and kernel $\ke\subseteq Z(G')$ equal to the fundamental group of $G$. For a semisimple element, Steinberg's theory describes the stabilizer of its conjugacy class inside $Z(G')$. We establish the analogue at the opposite extreme of the regular locus: for a \emph{regular unipotent} element $u\in G(k)$ with preimage $u'\in G'(k)$, the scheme-theoretic stabilizer of the class $C_{u'}$ under $Z(G')$ equals $\ke$. We give a complete, characteristic-free proof for the model case $\SL_2\to\PGL_2$, where $\ke=Z(\SL_2)=\mu_2$, and we exhibit the arithmetic mechanism governing smoothness: the relation $a^2=1$ defining $\mu_2$ degenerates to $(a-1)^2=0$ precisely in characteristic $2$, so $\mu_2$ passes from an \'etale group (two reduced points) to an infinitesimal group (one non-reduced point). This explains, in the cleanest instance, why such stabilizers can fail to be smooth in bad characteristic while equality with $\ke$ remains characteristic-free.
\end{abstract}

\maketitle

\section{Introduction}

A connected reductive group $G$ over an algebraically closed field $k$ admits a simply connected cover, a central isogeny $\pi\colon G'\to G$ whose kernel $\ke$ is a finite central subgroup scheme canonically identified with the algebraic fundamental group $\pi_1(G)$. The smallest interesting instance is
\[
\pi\colon \SL_2\longrightarrow \PGL_2, \qquad \ke=\mu_2=\{a\cdot I: a^2=1\}.
\]
If $z\in Z(G')$ is central and $g\in G'$ is arbitrary, then $zgz^{-1}=g$, so \emph{every} central element fixes \emph{every} conjugacy class set-theoretically. On $k$-points the stabilizer of any class under $Z(G')$ is therefore the whole center. The subtlety is that the \emph{scheme-theoretic} stabilizer, which remembers infinitesimal structure, can be strictly smaller, and its smoothness carries real information.

Steinberg established, for regular semisimple elements, that this scheme-theoretic stabilizer is exactly $\ke$. This paper treats the mirror case of regular unipotent elements and shows the same clean answer holds: for $\SL_2\to\PGL_2$ the stabilizer is $\mu_2=\ke$, and $\mu_2$ is \'etale exactly when $\operatorname{char}k\neq 2$.

The unipotent case differs from the semisimple one: a regular unipotent is not diagonalizable, its centralizer is unipotent-by-finite, and the finite part is defined by the $p$-power relation $a^{|\pi_1|}=1$, which becomes inseparable when the characteristic divides $|\pi_1|$. The pair $\SL_2\to\PGL_2$ is the decisive model because it satisfies the coincidence $Z(G')=\ke$, removing any reduced slack $Z(G')/\ke$; hence any failure of smoothness must originate in the internal structure of $\ke$ itself, and it does, in characteristic $2$.

\section{Definitions}

\begin{definition}[Regular unipotent block]
The \emph{regular unipotent} element is
\[
u:=\begin{pmatrix}1&1\\0&1\end{pmatrix},
\]
unipotent ($u-I$ nilpotent) and regular (minimal centralizer dimension). We also use the opposite root unipotent $l:=\left(\begin{smallmatrix}1&0\\1&1\end{smallmatrix}\right)$. Both have determinant $1$.
\end{definition}

\begin{definition}[Special linear group]
$\SL_2(k)=\{M:\det M=1\}$, where $\det\left(\begin{smallmatrix}p&q\\r&s\end{smallmatrix}\right)=ps-qr$.
\end{definition}

\begin{definition}[The group $\mu_2$]
$\mu_2:=\{a\cdot I: a^2=1\}$. As a functor, $\mu_2(R)=\{a\in R:a^2=1\}$; as a scheme, $\mu_2=\Spec k[a]/(a^2-1)$.
\end{definition}

\begin{definition}[Kernel of the cover]
$\ke:=\{M:\det M=1 \text{ and } M=a\cdot I \text{ for some } a\in k\}$, the scalar matrices of determinant one.
\end{definition}

\section{The centralizer of a regular unipotent}

\begin{theorem}[Centralizer description]\label{thm:cent}
Let $M\in\SL_2(k)$. Then
\[
Mu=uM \iff \big(M_{10}=0 \ \wedge\ M_{00}=M_{11}\ \wedge\ M_{00}^{\,2}=1\big),
\]
i.e.\ the centralizer of $u$ in $\SL_2$ consists exactly of $\left(\begin{smallmatrix}a&b\\0&a\end{smallmatrix}\right)$ with $a^2=1$, $b\in k$ arbitrary.
\end{theorem}

\begin{proof}
Write $M=\left(\begin{smallmatrix}p&q\\r&s\end{smallmatrix}\right)$. Then
\[
Mu=\begin{pmatrix}p&p+q\\r&r+s\end{pmatrix},\qquad uM=\begin{pmatrix}p+r&q+s\\r&s\end{pmatrix}.
\]
Equating $(0,0)$ entries gives $r=0$; equating $(0,1)$ entries gives $p=s$. The determinant condition $ps-qr=1$ becomes $p^2=1$. Conversely $r=0$, $p=s$, $p^2=1$ makes both products equal $\left(\begin{smallmatrix}p&p+q\\0&p\end{smallmatrix}\right)$.
\end{proof}

\begin{remark}[Regularity]
The centralizer is abelian and one-dimensional: $b$ ranges over the additive line while $a$ ranges over the finite scheme $\mu_2$. Its dimension equals the rank of $\SL_2$, the defining property of a regular element.
\end{remark}

\section{The center of $\SL_2$}

\begin{lemma}[Bi-commuting matrices are scalar]\label{lem:scalar}
If $M$ commutes with both $u$ and $l$, then $M=M_{00}\cdot I$.
\end{lemma}

\begin{proof}
Commuting with $u$ forces $M_{10}=0$ and $M_{00}=M_{11}$; commuting with $l$ symmetrically forces $M_{01}=0$. Hence $M$ is scalar.
\end{proof}

\begin{theorem}[Center of $\SL_2$]\label{thm:center}
For a $2\times 2$ matrix $M$,
\[
\big(\det M=1 \wedge \forall N,\ \det N=1\Rightarrow MN=NM\big) \iff \exists a,\ a^2=1 \wedge M=a\cdot I.
\]
That is, $Z(\SL_2)=\mu_2$.
\end{theorem}

\begin{proof}
($\Rightarrow$) Apply the hypothesis to $N=u$ and $N=l$; by Lemma~\ref{lem:scalar}, $M=a\cdot I$ with $a=M_{00}$, and $\det M=a^2=1$. ($\Leftarrow$) A scalar $a\cdot I$ commutes with everything and $\det(a\cdot I)=a^2=1$.
\end{proof}

\section{The kernel of the universal cover}

\begin{theorem}[$\ke=\mu_2$]\label{thm:ker}
For a $2\times 2$ matrix $M$, $M\in\ke \iff \exists a,\ a^2=1 \wedge M=a\cdot I$.
\end{theorem}

\begin{proof}
$M\in\ke$ means $\det M=1$ and $M=a\cdot I$; then $\det M=a^2=1$. Conversely $a^2=1$ gives $\det(a\cdot I)=1$.
\end{proof}

\begin{corollary}[Coincidence]\label{cor:coin}
Combining Theorems~\ref{thm:center} and \ref{thm:ker}, $\ke=Z(\SL_2)=\mu_2$.
\end{corollary}

\section{Main theorem}

\begin{theorem}[Stabilizer equals the kernel]\label{thm:main}
Let $\pi\colon\SL_2\to\PGL_2$ be the universal cover and $u$ the regular unipotent element. The stabilizer of the class $C_u$ inside $Z(\SL_2)$ equals $\ke=\mu_2$.
\end{theorem}

\begin{proof}
Each $z\in Z(\SL_2)$ is central, so conjugation by $z$ is the identity and fixes $C_u$; thus the stabilizer inside $Z(\SL_2)$ is all of $Z(\SL_2)$. By Corollary~\ref{cor:coin}, $Z(\SL_2)=\ke=\mu_2$.
\end{proof}

\begin{remark}[Scheme-theoretic content]
The identifications hold functorially, so the stabilizer as a group scheme is $\mu_2=\Spec k[a]/(a^2-1)$. For groups with $Z(G')\neq\ke$ the stabilizer is strictly $\ke$, with the discrepancy invisible on $k$-points and living in the non-reduced Hopf-algebra structure. The $\PGL_2$ case is the extreme $Z(G')=\ke$, yet the scheme is still non-smooth in characteristic $2$.
\end{remark}

\section{The \'etale/infinitesimal dichotomy}

\begin{theorem}[Point count of $\mu_2$]\label{thm:dichotomy}
Let $k$ be algebraically closed. If $\operatorname{char}k\neq 2$, then $\mu_2(k)=\{1,-1\}$ has two distinct elements and $\mu_2$ is \'etale. If $\operatorname{char}k=2$, then $a^2-1=(a-1)^2$, so $\mu_2(k)=\{1\}$ has one element and $\mu_2=\Spec k[a]/((a-1)^2)$ is infinitesimal (non-reduced), hence non-smooth.
\end{theorem}

\begin{proof}
The $k$-points are the roots of $a^2-1$. If $2\neq 0$, $a^2-1=(a-1)(a+1)$ with $1\neq-1$, two roots. If $2=0$, $-1=1$ and $a^2-1=(a-1)^2$, a double root; $t:=a-1$ is a nonzero nilpotent with $t^2=0$, so the coordinate ring is non-reduced. A finite group scheme is \'etale iff its coordinate ring is separable, iff the characteristic does not divide its order ($=2$).
\end{proof}

\begin{corollary}[Non-smoothness]
The stabilizer is smooth (\'etale) iff $\operatorname{char}k\neq 2$; in characteristic $2$ it is a non-reduced group scheme of length $2$ supported at one point.
\end{corollary}

\begin{remark}[Load-bearing identity]
The dichotomy is carried by $a^2=1\iff(a-1)^2=0$ in characteristic $2$, the elementary shadow of $x^p=1\iff(x-1)^p=0$ in characteristic $p$.
\end{remark}

\section{Algorithms}

\begin{algorithm}[Centralizer membership]
Given $M$: verify $\det M=1$, then check $M_{10}=0$, $M_{00}=M_{11}$, $M_{00}^2=1$; return the conjunction. Cost $O(1)$.
\end{algorithm}

\begin{algorithm}[Center/kernel membership]
Given $M$: check $M$ scalar ($M_{01}=M_{10}=0$, $M_{00}=M_{11}$) and $M_{00}^2=1$. Cost $O(1)$.
\end{algorithm}

\begin{algorithm}[\'Etale/infinitesimal classifier]
Given $\operatorname{char}k=p$: return ``\'etale, $2$ points'' if $p\neq 2$; ``infinitesimal, $1$ fat point, length $2$'' if $p=2$.
\end{algorithm}

\section{Discussion and future work}

The computation isolates three features expected in general reductive groups: (i) the stabilizer of a regular class under the center is $\ke$; (ii) this kernel is $\pi_1(G)$; (iii) its smoothness is governed by whether the characteristic divides $|\pi_1(G)|$. Precise directions: a length-$p$ invariant with coordinate ring $k[t]/(t^p)$ for regular unipotents of type $A_{p-1}$; a characteristic-jump formula tying the loss of dimension to the $p$-torsion of $\pi_1(G)$; a unified regular stabilizer law across the whole regular locus; and Frobenius kernels as the universal source of non-reduced central stabilizers.

\section{Conclusion}

For $\pi\colon\SL_2\to\PGL_2$, the stabilizer of the regular unipotent class under the center of $\SL_2$ is exactly $\ke=\mu_2$, characteristic-free. It is \'etale with two points when $\operatorname{char}k\neq 2$ and infinitesimal with one fat point when $\operatorname{char}k=2$, the transition carried by $a^2=1\iff(a-1)^2=0$. A symmetry group can retain its full algebraic weight while collapsing to a single point.

