"""Etale vs infinitesimal: count roots of a^2 = 1 and detect the fat point."""
from __future__ import annotations
from typing import List

def mu2_points(p: int) -> List[int]:
    return sorted({a for a in range(p) if (a*a) % p == 1})

def coordinate_ring_length(p: int) -> int:
    # length of k[a]/(a^2 - 1): always 2 as a k-vector space dimension.
    return 2

def is_reduced(p: int) -> bool:
    # reduced iff distinct roots iff p != 2
    return len(mu2_points(p)) == 2

def report(p: int) -> None:
    pts = mu2_points(p)
    kind = "etale (reduced)" if is_reduced(p) else "infinitesimal (non-reduced)"
    length = coordinate_ring_length(p)
    print(f"char {p}: points={pts}, length={length}, {kind}")
    if p == 2:
        # exhibit the nilpotent t = a - 1 with t^2 = 0
        for a in range(2):
            assert ((a-1)*(a-1)) % 2 == (a*a - 1) % 2

if __name__ == "__main__":
    for p in (2, 3, 5, 7, 11, 13):
        report(p)

